<script setup lang="ts">
import {Table,Popconfirm} from 'ant-design-vue'
import {formatTime} from '@starbeacon/shared/types.ts'
import {channelNames,severityOptions,streamNames,type Channel} from './notifications'
defineProps<{items:readonly Channel[];busy:boolean;available:boolean}>()
const emit=defineEmits<{edit:[record:Channel];test:[record:Channel]}>()
const columns=[{title:'渠道名称',dataIndex:'name',key:'name',width:210},{title:'类型',dataIndex:'kind',key:'kind',width:120},{title:'状态',key:'state',width:90},{title:'目标',dataIndex:'target',key:'target',width:220},{title:'日志类别',key:'streams',width:180},{title:'告警级别',key:'severities',width:160},{title:'静默截止',key:'muted',width:190},{title:'操作',key:'actions',width:150,fixed:'right' as const}]
</script>
<template><div class="table-wrap"><Table :columns="columns" :data-source="[...items]" row-key="id" :pagination="false" :scroll="{x:1320}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'">{{record.name}}<small class="record-id">修订 {{record.revision}}</small></template><template v-else-if="column.key==='kind'">{{channelNames[record.kind as keyof typeof channelNames]}}</template><template v-else-if="column.key==='state'"><span :class="['status',record.enabled?'status-online':'status-disabled']">{{record.enabled?'启用':'停用'}}</span></template><template v-else-if="column.key==='target'"><span class="technical">{{record.target}}</span></template><template v-else-if="column.key==='streams'">{{(record.streams??['alerts']).map((value:keyof typeof streamNames)=>streamNames[value]??value).join('、')}}</template><template v-else-if="column.key==='severities'">{{(record.streams??['alerts']).includes('alerts')?record.severities.map((value:string)=>severityOptions.find(item=>item.value===value)?.label??value).join('、'):'不订阅告警'}}</template><template v-else-if="column.key==='muted'">{{formatTime(record.muted_until)}}</template><template v-else-if="column.key==='actions'"><div class="filter-actions"><a-button type="link" size="small" :disabled="busy||!available" @click="emit('edit',record as Channel)">配置</a-button><Popconfirm title="向该渠道发送一条测试摘要？" description="测试会发送到渠道当前配置的接收目标。" ok-text="发送测试" cancel-text="取消" :disabled="busy||!available" @confirm="emit('test',record as Channel)"><a-button type="link" size="small" :disabled="busy||!available">测试</a-button></Popconfirm></div></template></template></Table></div></template>
